const root=document.getElementById('app');let chapter=0,clues=[],solved=false,route=null;
const names=['Айдар','Дана','Тимур'];const evidence=[{name:'Запись камеры',desc:'Видно, кто прошёл к серверной перед сбоем.',prob:[.8,.3,.2],detail:'Камера могла ошибиться: для каждого подозреваемого сигнал имеет свою вероятность.'},{name:'Журнал доступа',desc:'Обнаружена попытка отключить SANA.',prob:[.7,.2,.4],detail:'Данные журнала сильнее связаны с доступом Айдара.'},{name:'Фрагмент переписки',desc:'«Выключи проверку перед выставкой»',prob:[.3,.9,.4],detail:'Переписка чаще встречается при версии о причастности Даны.'}];
function bot(t){return `<div class="bot"><b>✳ QAIRUBOT</b>${t}</div>`}function frame(n,title,loc,story,quote,content){root.innerHTML=`<div class="game"><div class="game-head"><div class="chapter">ЭПИЗОД 0${n} / 03 · ${loc}</div><div class="progress"><span class="${n>=1?'on':''}"></span><span class="${n>=2?'on':''}"></span><span class="${n>=3?'on':''}"></span></div></div><div class="layout"><section class="story"><div class="scene"><div class="scene-label">● &nbsp; АСТАНА, 2040 &nbsp; / &nbsp; ${loc}</div></div><div class="story-content"><h1>${title}</h1><p>${story}</p>${bot(quote)}</div></section><section class="panel">${content}</section></div></div>`}function home(){root.innerHTML=`<section class="hero"><div><div class="eyebrow">ИНТЕРАКТИВНОЕ ПРИКЛЮЧЕНИЕ &nbsp; / &nbsp; 2026</div><h1>Последний<br><em>сигнал</em><br>Астаны.</h1><p class="lead">Завтра файнал. Сегодня отключилась городская система ИИ. Похоже, подготовка к экзамену будет немного необычной.</p><div class="actions"><button class="primary" onclick="start()">НАЧАТЬ ИГРУ &nbsp; ↗</button><span class="small-note">3 главы · примерно 10 минут</span></div></div><div class="art"><div class="city"></div><div class="art-top">● &nbsp; ПОДКЛЮЧЕНИЕ К ГОРОДУ...</div><div class="art-bottom"><span><strong>ASTANA / 2040</strong><br>Один студент. Один бот. И никакого Wi-Fi.</span><div class="artnum">01</div></div></div></section><div class="feature-row"><div class="feature"><span class="n">01 /</span><div><b>ИСТОРИЯ</b>Выбраться из QAIRU</div></div><div class="feature"><span class="n">02 /</span><div><b>ГОРОД</b>Найти путь к EXPO</div></div><div class="feature"><span class="n">03 /</span><div><b>РАССЛЕДОВАНИЕ</b>Раскрыть правду о SANA</div></div></div>`}function start(){chapter=1;clues=[];solved=false;route=null;show1()}document.getElementById('restart').onclick=()=>{if(confirm('Начать игру заново? Текущий прогресс исчезнет.'))start()};
const options={Аудитория:['красный','жёлтый'],Техническая:['красный','синий'],Выход:['синий','жёлтый']};const doors=Object.keys(options),colors=['красный','синий','жёлтый'];function solveCSP(){function visit(i,used,result){if(i===doors.length)return result;for(let c of options[doors[i]])if(!used.includes(c)){let r=visit(i+1,[...used,c],{...result,[doors[i]]:c});if(r)return r}return null}return visit(0,[],{})}
function show1(){chapter=1;frame(1,'Последняя пара','QAIRU','Вечер перед файналом. Свет мигает, Wi-Fi исчезает, а двери блокируются. На экране — последнее сообщение SANA: «Файнал не отменили. Помогите». Чтобы выйти, распредели пропуска по дверям.','По моим расчётам, задача решается за 12 секунд. Но я подожду.',`<div class="panel-top"><span class="tag">МИССИЯ 01 · CSP</span><span class="step-label">ВЫХОД ИЗ QAIRU</span></div><h2>Пропуск к свободе</h2><p>Назначь каждой двери один подходящий пропуск. Каждый цвет можно использовать только один раз.</p><div class="hint">🔴 Красный: аудитория или техническая<br>🔵 Синий: техническая или выход<br>🟡 Жёлтый: аудитория или выход</div><div class="fields">${doors.map((d,i)=>`<label class="field"><span>${['🚪','⚙️','↗'][i]} &nbsp; ${d}</span><select id="d${i}"><option value="">Выбери пропуск</option>${colors.map(c=>`<option>${c}</option>`).join('')}</select></label>`).join('')}</div><div class="controls"><button class="primary" onclick="checkCSP()">ПРОВЕРИТЬ РЕШЕНИЕ ↗</button><button class="secondary" onclick="hintCSP()">Помощь бота</button></div><div id="msg" class="message" aria-live="polite"></div><div id="next"></div><details class="explain"><summary>Как здесь работает CSP?</summary>Переменные — двери, их возможные значения — цвета пропусков. Алгоритм перебирает допустимые значения и возвращается назад, если нарушено ограничение. Каждый пропуск используется один раз.</details>`)}function checkCSP(){let values=doors.map((_,i)=>document.getElementById('d'+i).value),m=document.getElementById('msg');if(values.some(v=>!v)){m.textContent='Сначала выбери пропуск для каждой двери.';return}if(new Set(values).size!==3){m.textContent='Один пропуск нельзя использовать для двух дверей.';return}if(doors.some((d,i)=>!options[d].includes(values[i]))){m.textContent='Один из пропусков не подходит к своей двери. Проверь условия.';return}m.className='message good';m.textContent='✓ Все ограничения соблюдены. Двери открыты!';document.getElementById('next').innerHTML='<button class="primary advance" onclick="show2()">ВЫЙТИ В ГОРОД ↗</button>';solved=true}function hintCSP(){const s=solveCSP();doors.forEach((d,i)=>document.getElementById('d'+i).value=s[d]);document.getElementById('msg').textContent='Бот нашёл один допустимый вариант. Проверь его.'}
const points=[{name:'QAIRU',x:40,y:140},{name:'Остановка',x:165,y:65},{name:'Байтерек',x:170,y:190},{name:'Парк',x:290,y:75},{name:'Мост',x:305,y:190},{name:'EXPO',x:430,y:130}];const edges=[[0,1,4],[0,2,5],[1,3,5],[1,2,3],[2,4,4],[3,4,3],[3,5,4],[4,5,5]];function astar(block){let open=[0],g=Array(6).fill(Infinity),parent={},visited=[];g[0]=0;const h=i=>Math.hypot(points[i].x-points[5].x,points[i].y-points[5].y)/50;while(open.length){open.sort((a,b)=>(g[a]+h(a))-(g[b]+h(b)));let cur=open.shift();if(visited.includes(cur))continue;visited.push(cur);if(cur===5){let path=[5];while(path[0]!==0)path.unshift(parent[path[0]]);return {path,visited,cost:g[5]}}for(const [a,b,w] of edges){if(block&&((a===3&&b===5)||(a===5&&b===3)))continue;let next=a===cur?b:b===cur?a:null;if(next===null)continue;let n=g[cur]+w;if(n<g[next]){g[next]=n;parent[next]=cur;open.push(next)}}}return null}
function mapSVG(){return `<svg viewBox="0 0 480 250" role="img" aria-label="Учебная схема маршрута по Астане">${edges.map(([a,b])=>{let blocked=document.getElementById('block')?.checked&&a===3&&b===5,on=route?.path.some((v,i)=>i&&((v===a&&route.path[i-1]===b)||(v===b&&route.path[i-1]===a)));return `<line x1="${points[a].x}" y1="${points[a].y}" x2="${points[b].x}" y2="${points[b].y}" class="road ${blocked?'blocked':''} ${on?'path':''}"/>`}).join('')}${points.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="9" class="node ${route?.visited.includes(i)?'visited':''} ${route?.path.includes(i)?'path':''}"/><text x="${p.x}" y="${p.y+26}" text-anchor="middle">${p.name}</text>`).join('')}</svg>`}function show2(){chapter=2;route=null;frame(2,'Астана, мы идём','ГОРОД','Снаружи мороз, заряд телефона — 8%. Друг пишет: «Я бы помог, но я уже в общаге и снял носки». Последний сигнал SANA ведёт к EXPO.','Могу построить маршрут. Но за погоду в Астане не отвечаю.',`<div class="panel-top"><span class="tag">МИССИЯ 02 · A*</span><span class="step-label">ПУТЬ К EXPO</span></div><h2>Найди маршрут</h2><p>Учебная карта условная. Дороги имеют разную длину. Закрой один переход и посмотри, как изменится путь.</p><div id="map" class="map"></div><div class="controls"><label class="toggle"><input type="checkbox" id="block" onchange="route=null;drawMap();document.getElementById('route-result').textContent='';document.getElementById('next').innerHTML=''"> Закрыть дорогу Парк → EXPO</label></div><div class="controls"><button class="primary" onclick="runRoute()">ПОСТРОИТЬ МАРШРУТ ↗</button></div><div id="route-result" class="message" aria-live="polite"></div><div id="next"></div><details class="explain"><summary>Как здесь работает A*?</summary>A* сравнивает узлы по f = g + h: g — пройденная стоимость, h — оценка расстояния до цели. Зелёный путь — найденный маршрут; бирюзовые узлы — проверенные точки. Стоимости и карта условные.</details>`);drawMap()}function drawMap(){document.getElementById('map').innerHTML=mapSVG()}function runRoute(){route=astar(document.getElementById('block').checked);drawMap();let el=document.getElementById('route-result');if(!route){el.textContent='Маршрут недоступен.';return}el.className='message good';el.textContent=route.path.map(i=>points[i].name).join(' → ')+` · Длина: ${route.cost} усл. ед. · Проверено точек: ${route.visited.length}`;document.getElementById('next').innerHTML='<button class="primary advance" onclick="show3()">ПРИБЫТЬ К EXPO ↗</button>'}
function posterior(){let p=[1/3,1/3,1/3];for(let index of clues){p=p.map((v,i)=>v*evidence[index].prob[i]);let s=p.reduce((a,b)=>a+b,0);p=p.map(x=>x/s)}return p}function show3(){chapter=3;frame(3,'Кто отключил SANA?','EXPO','В серверной три человека имели доступ к системе. Камеры, журнал и переписка помогут разобраться. Ты можешь собрать улики или обвинить кого-то раньше — но торопиться рискованно.','Я оцениваю версии по данным нашей модели. Вероятность — ещё не доказательство.',`<div class="panel-top"><span class="tag">МИССИЯ 03 · БАЙЕС</span><span class="step-label">РАССЛЕДОВАНИЕ</span></div><h2>Собери улики</h2><p>Выбирай улики и следи, как меняется оценка каждой версии. Все числа — учебные предположения.</p><div id="clues" class="clues"></div><div id="bars" class="bars"></div><div id="details" class="hint">До улик все три версии равновероятны.</div><label class="field"><span>Кого обвинить?</span><select id="suspect"><option value="">Выбери человека</option>${names.map((n,i)=>`<option value="${i}">${n}</option>`).join('')}</select></label><div class="controls"><button class="primary" onclick="finish()">ПРИНЯТЬ РЕШЕНИЕ ↗</button></div><div id="msg" class="message" aria-live="polite"></div><details class="explain"><summary>Как здесь работает Байес?</summary>Начинаем с одинаковых вероятностей. Для каждой улики умножаем вероятность версии на вероятность увидеть улику при этой версии, затем нормируем значения до суммы 100%. Для упрощения улики считаются условно независимыми.</details>`);updateClues()}function updateClues(){let p=posterior();document.getElementById('clues').innerHTML=evidence.map((e,i)=>`<button class="clue" ${clues.includes(i)?'disabled':''} onclick="addClue(${i})"><b>${clues.includes(i)?'✓':'＋'} &nbsp; ${e.name}<br><small>${e.desc}</small></b><span>${clues.includes(i)?'ИЗУЧЕНО':'ИЗУЧИТЬ ↗'}</span></button>`).join('');document.getElementById('bars').innerHTML=p.map((v,i)=>`<div class="barline"><b>${names[i]}</b><div class="barbg"><i style="width:${v*100}%"></i></div><span>${Math.round(v*100)}%</span></div>`).join('')}function addClue(i){if(clues.includes(i))return;clues.push(i);updateClues();document.getElementById('details').textContent=evidence[i].detail}function finish(){const v=document.getElementById('suspect').value;if(v===''){document.getElementById('msg').textContent='Сначала выбери подозреваемого.';return}let correct=Number(v)===0;root.innerHTML=`<div class="end"><div class="eyebrow">${correct?'МИССИЯ ВЫПОЛНЕНА':'ДЕЛО НЕ ЗАКРЫТО'}</div><h1>${correct?'Астана снова на связи.':'Кажется, мы поспешили.'}</h1><p>${correct?'Ты нашёл Айдара: он отключил проверку SANA, чтобы скрыть ошибку в своём проекте. Система восстановлена.':'Ты обвинил '+names[Number(v)]+', но настоящий виновник — Айдар. Он отключил проверку SANA, скрывая ошибку в проекте. Систему восстановили, но расследование пришлось продолжить.'}</p>${bot(correct?'Отличная работа. Кстати, файнал по-прежнему завтра.':'В следующий раз соберём все улики? Моя модель любит данные.')}<p>Собрано улик: ${clues.length} из 3. ${clues.length<3?'Попробуй пройти расследование ещё раз и сравнить результаты.':'Ты собрал все улики и помог восстановить полную картину.'}</p><div class="actions" style="justify-content:center"><button class="primary" onclick="start()">СЫГРАТЬ ЕЩЁ РАЗ ↗</button><button class="secondary" onclick="home()">В начало</button></div></div>`}home();
